            background:
              "L'Amazon Research Association (ARA), un'organizzazione non profit che conduce studi di ecologia delle acque dolci in tutta l'Amazzonia peruviana, gestisce 6 stazioni di ricerca sul campo lungo i fiumi Ucayali e Marañón. La Ricercatrice Principale sul Campo, dott.ssa Sofia Huaman, si era sempre appoggiata a barche in alluminio con fuoribordo da 25 hp per i rilievi a transetto dei delfini di fiume (Inia geoffrensis) e delle lontre giganti (Pteronura brasiliensis). Tuttavia, uno studio acustico del 2023 aveva rivelato che il rumore del motore causava una riduzione del 47% degli avvistamenti in superficie dei delfini entro 500 m dall'imbarcazione durante il campionamento. Inoltre, la logistica del carburante per le stazioni remote costava 1.240 dollari al mese e richiedeva viaggi di 3 ore tra andata e ritorno in canoa di rifornimento. Huaman necessitava di una piattaforma silenziosa, a zero emissioni e portabile, capace di trasportare 2 ricercatori più 40 kg di attrezzatura di campionamento in giornate di rilievo di 8 ore.",
